import hashlib, json, re
from pathlib import Path

notice_ids = {'105806-2026', '105970-2026', '105743-2026'}
requirement = re.compile(r'\bmigrat\w*\b|import validation|data quality|data reconciliation|reporting data|acceptance criteria', re.I)
records = []
for path in sorted(Path('products/services').rglob('*.json')):
    if 'award' not in str(path).lower() and not any(n in path.name for n in notice_ids):
        continue
    if path.stat().st_size > 1048576:
        continue
    raw = path.read_bytes()
    try:
        package = json.loads(raw)
    except (ValueError, UnicodeError):
        continue
    if not isinstance(package, dict) or not isinstance(package.get('releases'), list):
        continue
    for release in package['releases']:
        if not isinstance(release, dict):
            continue
        notice = next((n for n in sorted(notice_ids) if n in str(release.get('id', '')) or n in path.name), None)
        if not notice:
            continue
        passages = []
        def collect(value, pointer):
            if isinstance(value, dict):
                for key, child in value.items():
                    collect(child, pointer + '/' + key.replace('~', '~0').replace('/', '~1'))
            elif isinstance(value, list):
                for index, child in enumerate(value):
                    collect(child, pointer + '/' + str(index))
            elif isinstance(value, str):
                match = requirement.search(value)
                if match:
                    start = max(0, match.start() - 160)
                    end = min(len(value), match.end() + 240)
                    passages.append({'field': pointer, 'character_offset': start, 'verbatim_excerpt': value[start:end]})
        collect(release, '')
        records.append({'notice': notice, 'path': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'release_id': release.get('id'), 'tags': release.get('tag'), 'candidate_passages': passages[:12]})
output = Path('products/services/awarded-supplier-qa/original-award-record-screen.json')
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps({'matched_records': records, 'missing_notice_ids': sorted(notice_ids - {r['notice'] for r in records}), 'limit': 'Local OCDS release-package screen. Read each full field and its context before treating an excerpt as a contract obligation. No supplier invitation was checked.'}, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
readback = json.loads(output.read_text(encoding='utf-8'))
print(json.dumps({'artifact': str(output), 'matched_records': len(readback['matched_records']), 'missing_notice_ids': readback['missing_notice_ids'], 'candidate_passages': sum(len(r['candidate_passages']) for r in readback['matched_records'])}))
